<?php
namespace Dth\Crm\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\{HasMany,BelongsTo,BelongsToMany}; use Dth\Crm\Support\{Normalizer,CodeGenerator};
class Company extends Model {use SoftDeletes;protected $table='crm_companies';protected $guarded=[];protected function casts():array{return ['metadata'=>'array'];}
 protected static function booted():void{static::saving(function(self $m){$n=app(Normalizer::class);if(blank($m->company_code)){$m->company_code=app(CodeGenerator::class)->make('COM');}$m->normalized_name=$n->companyName($m->legal_name)??'';$m->tax_code=$n->taxCode($m->tax_code);$m->normalized_phone=$n->phone($m->phone);if(!$m->email_domain && is_array($m->metadata))$m->email_domain=$n->domain($m->metadata['business_email']??null);});}
 public function contacts():BelongsToMany{return $this->belongsToMany(Contact::class,'crm_company_contacts','company_id','contact_id')->withPivot(['job_title','department','decision_role','is_primary','is_active'])->withTimestamps();} public function leads():HasMany{return $this->hasMany(Lead::class);} public function customers():HasMany{return $this->hasMany(Customer::class);} public function accountOwner():BelongsTo{return $this->belongsTo(Staff::class,'account_owner_staff_id');} public function assignments():HasMany{return $this->hasMany(CompanyAssignment::class);} }
